/* @autogenerated */
import { markdownBlocks } from './markdown-blocks';

describe('markdownBlocks', () => {
  it('reads headings, paragraphs with inline styles and links', async () => {
    const blocks = await markdownBlocks(
      '# Informe\n\nTexto **negrita** y *cursiva*, `código` y [enlace](https://x.test).',
    );
    expect(blocks[0]).toEqual({ kind: 'heading', level: 1, runs: [{ text: 'Informe' }] });
    expect(blocks[1]).toEqual({
      kind: 'paragraph',
      runs: [
        { text: 'Texto ' },
        { bold: true, text: 'negrita' },
        { text: ' y ' },
        { italic: true, text: 'cursiva' },
        { text: ', ' },
        { code: true, text: 'código' },
        { text: ' y ' },
        { link: 'https://x.test', text: 'enlace' },
        { text: '.' },
      ],
    });
  });

  it('reads tables with their alignment', async () => {
    const [table] = await markdownBlocks('| Sede | Plantas |\n|:--|--:|\n| Madrid | 2 |\n| Vigo | 0 |');
    expect(table).toEqual({
      kind: 'table',
      header: [[{ text: 'Sede' }], [{ text: 'Plantas' }]],
      rows: [
        [[{ text: 'Madrid' }], [{ text: '2' }]],
        [[{ text: 'Vigo' }], [{ text: '0' }]],
      ],
      align: ['left', 'right'],
    });
  });

  it('reads nested and ordered lists', async () => {
    const [list] = await markdownBlocks('3. Uno\n   - A\n4. Dos');
    expect(list.kind).toBe('list');
    const ordered = list as Extract<typeof list, { kind: 'list' }>;
    expect(ordered.ordered).toBeTrue();
    expect(ordered.start).toBe(3);
    expect(ordered.items[0][0]).toEqual({ kind: 'paragraph', runs: [{ text: 'Uno' }] });
    expect(ordered.items[0][1].kind).toBe('list');
  });

  it('turns the pagebreak comment into a page break and drops other html', async () => {
    const blocks = await markdownBlocks('Antes\n\n<!-- pagebreak -->\n\n<div>x</div>\n\nDespués');
    expect(blocks.map((block) => block.kind)).toEqual(['paragraph', 'pagebreak', 'paragraph']);
  });

  it('keeps escaped markdown characters as text', async () => {
    const [paragraph] = await markdownBlocks('A \\| B \\*C\\* &amp; D');
    const text = (paragraph as any).runs.map((run: any) => run.text).join('');
    expect(text).toBe('A | B *C* & D');
  });

  it('reads code, quotes and rules', async () => {
    const result = await markdownBlocks('```\nlet a = 1;\n```\n\n> quoted\n\n---');

    expect(result.map((block: any) => block.kind)).toEqual(['code', 'quote', 'rule']);
    expect((result[0] as any).text).toBe('let a = 1;');
    expect((result[1] as any).blocks[0].kind).toBe('paragraph');
  });

  it('reads struck text, line breaks and entities', async () => {
    const [paragraph] = (await markdownBlocks('one ~~two~~  \nthree &amp; four')) as any[];

    expect(paragraph.runs.some((run: any) => run.strike && run.text === 'two')).toBeTrue();
    expect(paragraph.runs.some((run: any) => run.break)).toBeTrue();
    expect(paragraph.runs.map((run: any) => run.text).join('')).toContain('three & four');
  });
});
